/**
 * A inclinação da Terra — porte de `componentes/viz/terra3d.js`.
 *
 * O eixo da Terra não é reto: ele pende ~23,5°. Reto demais e não haveria
 * estações — os polos congelariam de vez e os trópicos ferveriam sem trégua;
 * inclinado demais e as estações viravam extremos. A faixa estreita em que o
 * planeta fica ameno é o assunto do módulo, e o termômetro é o que a torna
 * visível: ele sobe e desce com o slider.
 *
 * Sobre a Terra ter deixado de ser uma esfera de Three.js, ver `globo.ts`.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  type EstadoDaViz,
  infoDe,
  limitar,
  numeroDe,
  paleta,
  retangulo,
  rodape,
  texto,
  titulo,
} from './desenho.ts';
import { CONTINENTES, globo } from './globo.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

const ALVO_PADRAO = 23.5;
const TOL_PADRAO = 3;
/** Extremos da escala do termômetro, em °C. */
const MIN = -60;
const MAX = 100;

const terra3d: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  /** O termômetro do planeta: azul congelando, verde ameno, vermelho fervendo. */
  function termometro(
    ctx: CanvasRenderingContext2D,
    x: number,
    topo: number,
    altura: number,
    temperatura: number,
    modo: 'frio' | 'ameno' | 'quente',
  ): void {
    const cor = paleta();
    const tinta = modo === 'frio' ? cor.azulClaro : modo === 'quente' ? cor.erro : cor.verde;

    const largura = limitar(altura * 0.09, 10, 18);
    const bulbo = largura * 1.5;
    const base = topo + altura - bulbo;
    const escalaAltura = base - topo;

    const yDe = (temp: number): number =>
      base - ((limitar(temp, MIN, MAX) - MIN) / (MAX - MIN)) * escalaAltura;

    // Tubo e bulbo, vazios.
    retangulo(
      ctx,
      x - largura / 2,
      topo,
      largura,
      base - topo + bulbo,
      largura / 2,
      cor.fundo,
      tinta,
      2.5,
    );
    ctx.fillStyle = cor.fundo;
    ctx.strokeStyle = tinta;
    ctx.lineWidth = 2.5;
    ctx.beginPath();
    ctx.arc(x, base + bulbo * 0.6, bulbo, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();

    // O mercúrio.
    ctx.fillStyle = tinta;
    ctx.beginPath();
    ctx.arc(x, base + bulbo * 0.6, bulbo * 0.72, 0, Math.PI * 2);
    ctx.fill();
    const y = yDe(temperatura);
    ctx.fillRect(x - largura * 0.28, y, largura * 0.56, base + bulbo * 0.6 - y);

    // A escala.
    const miudo = limitar(altura * 0.045, 8, 12);
    ctx.strokeStyle = cor.trilho;
    ctx.lineWidth = 1.5;
    for (const marca of [-40, 0, 40, 80]) {
      const yy = yDe(marca);
      ctx.beginPath();
      ctx.moveTo(x + largura * 0.6, yy);
      ctx.lineTo(x + largura * 0.95, yy);
      ctx.stroke();
      texto(ctx, `${marca}°`, x + largura * 1.15, yy, miudo, {
        cor: cor.fraco,
        alinhamento: 'left',
      });
    }

    texto(ctx, `${Math.round(temperatura)}°`, x - largura * 0.9, y, miudo * 1.35, {
      cor: tinta,
      peso: 800,
      alinhamento: 'right',
    });

    texto(
      ctx,
      modo === 'frio' ? 'Congelando' : modo === 'quente' ? 'Fervendo' : 'Clima ameno',
      x,
      topo - miudo * 1.6,
      miudo * 1.2,
      { cor: tinta, peso: 800 },
    );
  }

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const inclinacao = numeroDe(valores, 't', 0);
    const ok = info.ok === true;
    const alvo = numeroDe(info, 'alvo', ALVO_PADRAO);
    const tolerancia = numeroDe(info, 'tol', TOL_PADRAO);

    const desvio = inclinacao - alvo;
    const fora = Math.max(0, Math.abs(desvio) - tolerancia);
    // Uma temperatura só, e direcional: eixo reto esfria, eixo deitado esquenta.
    const temperatura = 15 + desvio * 3;
    const modo = fora <= 0 ? 'ameno' : desvio < 0 ? 'frio' : 'quente';

    titulo(ctx, L, A, 'O eixo que dá as estações');

    const cx = L * 0.36;
    const cy = A * 0.54;
    const R = Math.min(L * 0.3, A * 0.28);

    // O eixo, inclinado — é ele o controle, então vem antes do planeta.
    const rad = (inclinacao * Math.PI) / 180;
    const meio = R * 1.45;
    ctx.strokeStyle = fora <= 0 ? cor.verde : cor.fraco;
    ctx.lineWidth = 2;
    ctx.setLineDash([6, 4]);
    ctx.beginPath();
    ctx.moveTo(cx - Math.sin(rad) * meio, cy - Math.cos(rad) * meio);
    ctx.lineTo(cx + Math.sin(rad) * meio, cy + Math.cos(rad) * meio);
    ctx.stroke();
    ctx.setLineDash([]);

    // A vertical de referência: sem ela não se vê de quanto é a inclinação.
    ctx.strokeStyle = cor.trilho;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(cx, cy - meio);
    ctx.lineTo(cx, cy + meio);
    ctx.stroke();

    // O planeta, pintado de gelo ou de brasa conforme se afasta da faixa.
    const intensidade = Math.min(0.85, fora / 16);
    const oceano: readonly [string, string] =
      fora <= 0
        ? ['#1b86dc', '#0a2c5c']
        : desvio < 0
          ? ['#7fb8e6', '#3d6a9c']
          : ['#c2662f', '#7a3115'];

    globo(ctx, cx, cy, R, {
      giro: t * 14,
      oceano,
      manchas: CONTINENTES,
      calotas: true,
      atmosfera: true,
      luz: 1 - intensidade * 0.35,
    });

    texto(
      ctx,
      `${inclinacao.toString().replace('.', ',')}°`,
      cx,
      cy + R * 1.45,
      limitar(A * 0.055, 12, 20),
      { cor: fora <= 0 ? cor.verde : cor.texto, peso: 800 },
    );

    termometro(ctx, L * 0.83, A * 0.24, A * 0.58, temperatura, modo);

    rodape(
      ctx,
      L,
      A,
      ok,
      'Cerca de 23,5°: estações equilibradas, clima ameno ✔',
      desvio < 0
        ? 'Eixo reto demais: quase sem estações — os polos congelam.'
        : 'Eixo inclinado demais: estações extremas, clima instável.',
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default terra3d;
